#if HOT_UPDATER_SANDBOX_LAYER
import CoreText
import Foundation

/// Geist and Geist Mono, from vercel/geist-font v1.8.2 under the SIL Open Font
/// License 1.1 (HotUpdaterSandboxFonts-OFL.md here, and each file's own name table). They live
/// in this file, not as resources, so only a sandbox build carries them, and
/// they're registered for this process on the screen's first use.
enum HotUpdaterSandboxFonts {
    private static let registered: Void = {
        for encoded in [geistRegular, geistMedium, geistSemiBold, geistMonoRegular, geistMonoMedium] {
            guard let data = Data(base64Encoded: encoded, options: .ignoreUnknownCharacters),
                  let provider = CGDataProvider(data: data as CFData),
                  let font = CGFont(provider) else { continue }
            var error: Unmanaged<CFError>?
            if !CTFontManagerRegisterGraphicsFont(font, &error) {
                NSLog("[HotUpdaterSandbox] font not registered: %@", String(describing: error?.takeRetainedValue()))
            }
        }
    }()

    static func register() {
        _ = registered
    }

